# ============================================================== binwalk
GUIDES.append(dict(
    name="binwalk", section="1", one_line="search a binary file for embedded files and executable code",
    plain=["`binwalk` scans a file for other files hidden inside it. Many files are really containers: a firmware image holds a filesystem, a kernel and compressed blobs; a picture can have a ZIP glued on its end; a PDF can hold scripts.",
           "It looks for magic numbers (the signature bytes that start a ZIP, PNG, gzip, ELF...), prints each hit with its offset, and can carve the pieces out into folders. It can also measure entropy: very random data is usually encrypted or compressed, plain data is not.",
           "In CTFs it answers 'is there something inside this file?' in seconds."],
    when=["A challenge image or file seems larger than it should be.", "Look inside a router or IoT firmware image.", "Extract an appended archive from a picture.", "Find which parts of a file are compressed or encrypted (entropy).", "Disassemble-guess a blob of code to see its CPU type."],
    examples=[("Scan a file for hidden content", "binwalk mystery.jpg", "Prints a table of DECIMAL offset, HEX offset and DESCRIPTION. A second hit such as 'Zip archive data' at a large offset means a ZIP is appended to the picture."),
              ("Extract everything it finds", "binwalk -e mystery.jpg", "-e carves the pieces out into a folder named _mystery.jpg.extracted. Needs helper tools such as unzip or 7z installed."),
              ("Extract and unpack recursively", "binwalk -Me firmware.bin", "-M follows the extraction: contents of contents are scanned again, as in firmware that contains a filesystem that contains archives."),
              ("Draw an entropy graph", "binwalk -E firmware.bin", "-E calculates entropy and plots it. A flat line near 1.0 is encrypted or compressed; low and varied is ordinary data. Use -N to skip the plot window."),
              ("Look for CPU code", "binwalk -A firmware.bin", "-A searches for common instruction patterns (ARM, MIPS, x86...), useful when you do not know the architecture."),
              ("Scan only for certain signatures", "binwalk -y zip -y png mystery.jpg", "-y keeps only these signature types, so a noisy file gives a short list."),
              ("Skip noisy signatures", "binwalk -x gzip -x lzma firmware.bin", "-x excludes types that produce lots of false hits."),
              ("Show raw text hits", "binwalk -R '\\x50\\x4b\\x03\\x04' mystery.jpg", "-R searches for your own byte sequence (here the ZIP header PK\\x03\\x04) and prints each offset."),
              ("Carve by hand with dd", "dd if=mystery.jpg of=hidden.zip bs=1 skip=48210", "Binwalk gave you an offset (48210). dd copies from there to a new file. Great when automatic extraction fails."),
              ("Analyse many files", "binwalk -r *.bin", "-r keeps going through a list of files and writes a short summary for each.")],
    options=[
        ("-B, --signature", "Scan for known file signatures (the default scan).", "Normal use."),
        ("-R, --raw=STR", "Search for a raw byte string.", "Your own signature."),
        ("-A, --opcodes", "Scan for common executable opcodes of many CPUs.", "Unknown code blobs."),
        ("-m, --magic=FILE", "Use another magic signature file.", "Custom signatures."),
        ("-b, --dumb", "Disable the smart signature keywords (show every match).", "Seeing every hit, even false ones."),
        ("-I, --invalid", "Show results that were marked invalid.", "Hunting damaged data."),
        ("-x, --exclude=STR", "Exclude matches whose description matches STR.", "Reducing noise."),
        ("-y, --include=STR", "Include only matches whose description matches STR.", "Looking for one thing."),
        ("-e, --extract", "Extract known file types.", "Pulling files out."),
        ("-D, --dd=TYPE:EXT:CMD", "Extract signatures of the given type, with a file extension and an optional command.", "Custom extraction."),
        ("-M, --matryoshka", "Recursively scan extracted files (like Russian dolls).", "Nested firmware."),
        ("-d, --depth=NUM", "Limit how deep -M goes (default 8).", "Stopping endless recursion."),
        ("-C, --directory=DIR", "Extract into this directory.", "Neat output."),
        ("-j, --size=NUM", "Limit the size of each extracted file.", "Space limits."),
        ("-n, --count=NUM", "Stop after this many extractions.", "Quick tests."),
        ("-r, --rm", "Delete carved files after extraction.", "Cleanup."),
        ("-z, --carve", "Carve data from the file even when the extractor is missing.", "Raw carving."),
        ("-E, --entropy", "Calculate file entropy.", "Finding encrypted or compressed areas."),
        ("-F, --fast", "Quicker entropy using fewer bytes.", "Speed."),
        ("-J, --save", "Save the entropy plot as a PNG.", "Reports."),
        ("-Q, --nlegend", "Omit the legend from the entropy plot.", "Clean plots."),
        ("-N, --nplot", "Do not plot the entropy graph.", "Text-only entropy."),
        ("-H, --high=FLOAT", "High entropy trigger (default 0.95).", "Tuning."),
        ("-L, --low=FLOAT", "Low entropy trigger (default 0.85).", "Tuning."),
        ("-W, --hexdump", "Hex dump a file, or compare files byte by byte.", "Comparing versions."),
        ("-G, --green", "Show only bytes that match in all files in -W.", "Common parts."),
        ("-i, --red", "Show only bytes that differ.", "Differences."),
        ("-U, --blue", "Show only bytes unique to a file.", "Comparison."),
        ("-w, --terse", "Terse hex dump.", "Compact view."),
        ("-o, --offset=OFFSET", "Start the scan at this offset.", "Skipping a header."),
        ("-l, --length=LENGTH", "Scan only this many bytes.", "A focused scan."),
        ("-g, --grep=STR", "Grep for text in the output.", "Filtering."),
        ("-f, --log=FILE", "Log results to a file.", "Records."),
        ("-c, --csv", "Log in CSV.", "Spreadsheets."),
        ("-t, --term", "Format output for the terminal width.", "Pretty."),
        ("-q, --quiet", "Suppress output.", "Scripts."),
        ("-v, --verbose", "Be verbose.", "More detail."),
        ("-a, --finclude", "Only scan files matching a regex.", "Mixed folders."),
        ("-p, --fexclude", "Skip files matching a regex.", "Mixed folders."),
        ("-s, --status", "Show a status server on this port.", "Long scans."),
        ("--run-as=USER", "Drop privileges to this user when extracting.", "Safer extraction."),
        ("--preserve-symlinks", "Keep symlinks that point outside the extraction directory.", "Understanding a firmware's structure; treat with care."),
        ("--no-symlinks", "Do not create symlinks when extracting.", "Safer extraction."),
        ("-V, --version", "Show the version.", "Check the install."),
        ("-h, --help", "Show help.", "A reminder.")],
    mistakes=["Running -e as root on an untrusted file: extraction can follow malicious symlinks. Run it as a normal user in a throw-away folder.", "Taking every hit as real: many 'matches' are false positives. Check the offset and the size.", "Missing the extraction tools (unzip, 7z, sasquatch, jefferson): binwalk then finds but cannot extract.", "Forgetting -M for nested containers: you only get the first layer.", "Not looking at the end of the file: use tail -c and xxd as well."],
    try_=["Append a zip to a picture with cat pic.jpg secret.zip > both.jpg, then find it with binwalk both.jpg.", "Extract it with -e and read the result.", "Run binwalk -E on a ZIP and on a text file and compare the entropy.", "Use dd with an offset binwalk reports to carve a part by hand."],
    see_also="file(1), xxd(1), strings(1), dd(1), foremost(1), exiftool(1), unzip(1), and the 7z / sasquatch tools used for extraction."))
